(()=>{const IMAGES={myvi:'data:image/jpeg;base64,[... trimmed for length ...]',crv:'data:image/jpeg;base64,[... trimmed for length ...]'};const apply=()=>{document.querySelectorAll('img').forEach(img=>{const s=(img.getAttribute('src')||'').toLowerCase();if(s.includes('myvi-real.jpg'))img.src=IMAGES.myvi;if(s.includes('crv-real.jpg'))img.src=IMAGES.crv;});};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply);else apply();})();